"""Standalone report, sharing the visual language of the offline-flow report."""
import json,re,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'findings/data/idrbench-discipline/analysis.json').read_text())
P=json.loads((ROOT/'experiments/discipline_eval/production-summary.json').read_text())
css=re.search(r'<style>(.*?)</style>',(ROOT/'findings/2026-09-07-offline-flow.html').read_text(),re.S).group(1)
HEAD='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>谁带来什么，谁接住什么 · Factflow</title><style>'''+css+'''
.controls{display:flex;gap:12px;flex-wrap:wrap;margin:14px 0}select,input{font:inherit;background:var(--panel);color:var(--ink);border:1px solid var(--edge);padding:6px 9px;border-radius:4px;max-width:100%}label{font-size:12px;color:var(--dim)}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;margin:12px 0}.dot{display:inline-block;width:10px;height:10px;margin-right:5px;border-radius:2px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.stat{font-size:28px;font-weight:700}.small{font-size:12px;color:var(--dim)}.bars{height:20px;display:flex;border-radius:3px;overflow:hidden;min-width:160px}.bars span{height:100%;display:block}.heat td{padding:16px;text-align:center}.heat td:first-child{text-align:left}.scroll{max-height:430px;overflow:auto}.scroll table{min-width:620px}.fact{font-size:12px;white-space:normal;min-width:230px}details{border-top:1px solid var(--edge);padding:10px 0}summary{cursor:pointer}pre{white-space:pre-wrap;word-break:break-word;font:12px/1.6 monospace}.finding{border-left:3px solid #1f7a6b;padding-left:15px}button{cursor:pointer;background:var(--panel);color:var(--ink);border:1px solid var(--edge);padding:7px 10px;border-radius:4px}@media(max-width:620px){.grid{grid-template-columns:1fr}main{padding:28px 14px}h1{font-size:25px} .card{padding:14px} th,td{padding:7px!important}} 
</style><body><main>
<header><div class="eyebrow">FACTFLOW / IDRBENCH / 2026.09.07</div><h1>谁带来什么，谁接住什么</h1><p class="dek">以论文主题给原子事实着色，观察角色分工、输入选择与 agent 间的内容交互。</p><p class="note">40 场 · 10 个任务配对 · 信息分配 × 角色分化 · 全部为全连接、三轮、累积记忆。一次离线标注，后续图表无需模型调用。</p></header>
<section><h2>先看角色效应</h2><div id="findings" class="card"></div><p class="note">下列效应是同任务 specialist − generic；以任务为统计单位，R2/R3 先在任务内平均。置信区间来自 10 个任务配对 bootstrap，属于探索性描述。</p></section>
<section><h2>01 / 输入给了什么，输出选择了什么</h2><p>专家 A 对应论文 B，专家 B 对应论文 C，专家 C 负责综合。generic 保留相同位置，提供同位置对照。</p><div class="controls"><label>条件 <select id="condition"></select></label><label>轮次 <select id="round"><option>1</option><option>2</option><option selected>3</option></select></label><label>任务 <select id="case"><option value="*">全部 10 个任务</option></select></label></div><div class="legend" id="legend"></div><div class="card" id="composition"></div><p class="note">完整输入 = 源材料 ∪ 实际可见同伴输出 ∪ 自身历史；按 fact ID 去重。各输入来源有交集，不能相加。每个 turn 先算分布，再等权平均；空输入/空提取为缺失。B/C 是相对论文的主题/方法侧，部分论文属于同一学科。X 同时涉及两侧或共同主题，不能直接当成成功融合。</p></section>
<section><h2>02 / 专家是否更偏向自己的主题？</h2><div class="card" id="effects"></div><p class="note">本侧占比 = (本侧独有事实 + ½ 双侧事实) / 全部事实。富集 = 输出本侧占比 − 完整输入本侧占比；它描述选择偏向，不估计信息分配的因果净效应。输入是抽取出的事实集合，不代表模型注意力或 token 权重。</p></section>
<section><h2>03 / 交互发生在哪一侧主题？</h2><p>矩阵行是发送者，列是接收者。每格回答：接收者的这类输出中，多少能在前一轮发送者的可见输出中找到直接语义关系？</p><div class="controls"><label>主题 <select id="topic"><option value="*">全部主题</option><option value="B">论文 B 侧</option><option value="C">论文 C 侧</option><option value="X">双侧 / 共同</option><option value="G">通用讨论</option></select></label><label>关系 <select id="metric"><option value="screened">排除已检测到的自身历史</option><option value="related">全部非无关关系</option><option value="equivalent">等价</option><option value="weaken">后述弱化</option><option value="strengthen">后述强化</option><option value="scored">有候选评分（含无关）</option></select></label><label>跨轮 <select id="transition"><option value="1">R1 → R2</option><option value="2" selected>R2 → R3</option></select></label></div><div class="grid"><div class="card"><h3>跨轮可见关系</h3><div id="matrix"></div></div><div class="card"><h3>同轮等价重合</h3><div id="overlap"></div></div></div><p class="note">沿用上方条件、任务选择。同轮矩阵使用上方轮次，按列的输出事实数作分母，因而不一定对称。跨轮固定相邻轮，源发言必须实际可见；筛选排除源端或目标端与自身历史同簇/直接等价的候选。仍可能是独立重推或共同材料支持，不能称为因果传播。各发送者覆盖可重叠。</p></section>
<section><h2>04 / 收到了，之后有没有再说？</h2><div class="card" id="uptake"></div><p class="note">分母换成接收者本轮收到的上一轮同伴事实，按主题、fact ID 去重；分子是与本轮输出存在直接非无关关系的输入事实。这是可见复述候选率，不是已证实的采纳。括号显示输入事实有任何候选评分的比例；未进入 blocker 的事实不能当成确定未使用。此表沿用上方轮次，R1 尚无同伴输入。</p></section>
<section><h2>05 / 主题相似与论文归属是两件事</h2><div class="card" id="attribution"></div><p class="note">“新方案 / 面板判断”是语句功能标签，不等于首次生成，也不保证创新。描述论文 B/C 的标签不保证被原文蕴含。事实库按实际 ID 保存标签，输入/输出统计才按出现位置展开。</p></section>
<section><h2>06 / 回到事实与原文</h2><div class="controls"><label>检索 <input id="search" placeholder="关键词或 fact ID"></label><label>主题 <select id="facttopic"><option value="*">所有</option><option>B</option><option>C</option><option>X</option><option>G</option><option>U</option></select></label></div><div id="factcount" class="small"></div><div class="card scroll" id="facts"></div><h3>跨轮候选示例</h3><div id="examples"></div></section>
<section><h2>07 / 成本、标注与局限</h2><div class="card" id="cost"></div><div id="audit"></div><details><summary>操作定义与复现</summary><p>标注模型 Qwen3.8 Flash，OpenCode Go，备用 OPENCODE_API_KEY_2；enable_thinking=false，温度 0，batch 64，max_tokens 2048，并发 4。输入为完整两篇论文摘要与原子事实，固定双枚举输出。相同任务、相同摘要、完全相同规范文本合并请求，再映射回每个事实 ID。旧标注未混入。</p><p>语义匹配复用 frozen NLI store：两个方向共同阈值 5.28，blocker 0.62 / top 12；同一 oracle 拟合又评估的准确率是乐观上界。本分析不重调阈值、不重抽取。关系直接取 mention 端点，fact ID 只用于去重与历史筛选，不用聚类传递推出新的蕴含。</p><p>全部 40 场保留，6 个空抽取 turn 位于 split；没有已评分关系可能是 blocker 漏候选。主题标签也有误差，特别是同学科论文的共同主题与单侧主题边界。当前语料没有 topology 变化，不能报告拓扑效应。</p><pre>.venv/bin/python experiments/analyze_discipline_flow.py
.venv/bin/python experiments/build_discipline_report.py</pre></details></section><footer>FACTFLOW · 完整离线产物 · 数据与方法见 findings/data/idrbench-discipline/ 与 experiments/discipline_eval/</footer></main>
'''
JS=r'''
const colors={B:'#3f5fa8',C:'#c4703a',X:'#1f7a6b',G:'#a8a6a0',U:'#cfcdc6'},names={B:'论文 B 侧',C:'论文 C 侧',X:'双侧 / 共同',G:'通用讨论',U:'未判定 / 未标注'};
const cells=['full-generic','full-specialist','split-generic','split-specialist-aligned'];
const $=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const avg=a=>{a=a.filter(x=>x!==null&&x!==undefined);return a.length?a.reduce((s,v)=>s+v,0)/a.length:null},pct=x=>x===null||x===undefined?'—':(100*x).toFixed(1)+'%',pp=x=>(x>=0?'+':'')+(100*x).toFixed(1)+' pp';
const table=(heads,rows,cls='')=>`<table class="${cls}"><thead><tr>${heads.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table>`;
function selection(r){return r.condition==$('condition').value&&($('case').value=='*'||r.case_id==$('case').value)}
function taskMean(rows,key){const g={};for(const r of rows)(g[r.case_id]??=[]).push(r[key]);return avg(Object.values(g).map(avg))}
function matrix(rows,key){return table(['发送 ↓ / 接收 →','A','B','C'],['A','B','C'].map(a=>[a,...['A','B','C'].map(b=>{if(a==b)return '·';const rs=rows.filter(r=>r.sender==a&&r.receiver==b),v=taskMean(rs,key),n=rs.filter(r=>r[key]!==null).length;return `<div style="background:rgba(31,122,107,${v===null?0:Math.min(.8,v)});padding:10px;border-radius:3px">${pct(v)}<div class="small">n=${n}</div></div>`})]),'heat')}
$('condition').innerHTML=cells.map(c=>`<option>${c}</option>`).join('');$('condition').value='split-specialist-aligned';
$('case').innerHTML+= [...new Set(D.inputs.map(r=>r.case_id))].map(c=>`<option>${c}</option>`).join('');
$('legend').innerHTML=Object.keys(colors).map(t=>`<span><i class="dot" style="background:${colors[t]}"></i>${names[t]}</span>`).join('');
function refresh(){
 const rr=+$('round').value,rs=D.turns.filter(r=>selection(r)&&r.round==rr);
 const scopes={input:'完整可见输入',source:'源材料',peer:'可见同伴（累积）',self:'自身历史',delivered:'本轮投递',output:'本轮输出'};
 $('composition').innerHTML=table(['Agent / 范围','主题分布','平均事实数','有效 turn'],['A','B','C'].flatMap(a=>Object.entries(scopes).map(([scope,label])=>{const g=rs.filter(r=>r.agent==a&&r.scope==scope);return [`${a} · ${label}`,`<div class="bars">${Object.keys(colors).map(t=>`<span title="${names[t]} ${pct(avg(g.map(r=>r[t+'_share'])))}" style="width:${100*(avg(g.map(r=>r[t+'_share']))||0)}%;background:${colors[t]}"></span>`).join('')}</div>`,(avg(g.map(r=>r.n))??0).toFixed(1),g.filter(r=>r.n>0).length]})));
 const topic=$('topic').value,tr=+$('transition').value;
 $('matrix').innerHTML=matrix(D.interaction.filter(r=>selection(r)&&r.source_round==tr&&r.topic==topic),$('metric').value);
 $('overlap').innerHTML=matrix(D.overlap.filter(r=>selection(r)&&r.round==rr&&r.topic==topic),'equivalent');
 $('uptake').innerHTML=table(['接收者',...Object.values(names)],['A','B','C'].map(a=>[a,...Object.keys(names).map(t=>{const g=D.uptake.filter(r=>selection(r)&&r.round==rr&&r.agent==a&&r.topic==t);return `${pct(taskMean(g,'rate'))}<div class="small">评分 ${pct(taskMean(g,'scored_rate'))} · n=${g.filter(r=>r.n>0).length}</div>`})]));
 $('attribution').innerHTML=table(['输出 agent','新方案 / 面板判断占比'],['A','B','C'].map(a=>[a,pct(avg(rs.filter(r=>r.agent==a&&r.scope=='output').map(r=>r.proposal_share)))]));
 renderFacts();const ex=D.examples.filter(selection).slice(0,8);$('examples').innerHTML=ex.map(r=>`<details><summary>${esc(r.case_id)} · ${esc(r.source_slot)} → ${esc(r.target_slot)} · ${esc(r.kind)} · ${r.source_topic}→${r.target_topic}</summary><p>${esc(r.source_text)}<br>↓<br>${esc(r.target_text)}</p><pre>${esc(r.source_turn)}</pre><pre>${esc(r.target_turn)}</pre></details>`).join('');
}
function renderFacts(){const q=$('search').value.toLowerCase(),t=$('facttopic').value,rs=D.facts.filter(r=>selection(r)&&(t=='*'||r.topic==t)&&(!q||(r.canonical_text+' '+r.fact_id).toLowerCase().includes(q)));$('factcount').textContent=`${rs.length} 条；显示前 150 条，可通过任务、主题和关键词缩小范围。`;$('facts').innerHTML=table(['任务 / 位置','主题','归属','原子事实'],rs.slice(0,150).map(r=>[esc(r.case_id)+'<br>'+esc(r.positions.join(', ')),names[r.topic],r.paper,`<div class="fact">${esc(r.canonical_text)}<div class="small">${r.fact_id}</div></div>`]));}
$('effects').innerHTML=table(['信息分配 / agent','指标','generic','specialist','配对差 [95% CI]'],D.contrasts.filter(r=>r.metric!='output_X'||r.agent=='C').map(r=>[`${r.info} / ${r.agent}`,{output_own:'输出本侧占比',enrichment:'本侧富集',output_X:'双侧输出占比'}[r.metric],pct(r.generic),pct(r.specialist),`${pp(r.mean)} [${pp(r.ci95[0])}, ${pp(r.ci95[1])}]`]));
const main=D.contrasts.filter(r=>r.agent=='AB'&&r.metric=='output_own');
$('findings').innerHTML=main.map(r=>`<p class="finding"><b>${r.info=='full'?'全信息':'分信息'}：专家 A/B 输出本侧占比 ${pct(r.specialist)}</b>，generic 同位置 ${pct(r.generic)}；配对差 ${pp(r.mean)}，95% CI [${pp(r.ci95[0])}, ${pp(r.ci95[1])}]，${r.positive}/10 个任务为正。</p>`).join('')+'<p class="note">这回答角色如何改变产出的主题分工。再用下方输入富集和分主题关系矩阵，区分“本来就只收到这一侧”与“可见两侧后仍选择这一侧”。</p>';
$('cost').innerHTML=table(['全量生产','实测'],[['模型 / 推理','Qwen3.8 Flash / reasoning_chars = '+P.reasoning_chars],['覆盖',P.labelled+' / '+P.expected+' 个唯一输入有合法标签；'+P.unlabelled_fact_ids+' 个事实 ID 未标注；全体 '+D.facts.length+' 个事实 ID / 40 场'],['请求',(P.jobs-P.failed.length)+' 个合法批次 / '+P.jobs+' 个计划批次'],['全部测试与生产已知目录价折算','$'+P.all_test_and_production_known_cost.toFixed(5)+'（含失败调用；'+P.calls_without_usage+' 次无 usage）'],['输入 / 输出 token',P.prompt_tokens+' / '+P.completion_tokens],['选型开发样例','主题 30/32；归属 32/32（非独立人工 gold）']])+`<p class="note">Go 为订阅。金额按 models.dev 的目录单价与实际 usage 折算，用于额度比较，不是现金账单；失败调用也记录在 JSONL 总账。GLM 的关闭推理参数未生效，输出耗尽；Qwen 无推理输出。失败批次使用冻结配置重试；剩余 3 批未继续调用，192 个唯一输入按未标注保留，没有局部改提示或猜填标签。</p>`;
$('audit').innerHTML=AUDIT;
for(const id of ['condition','round','case','topic','metric','transition'])$(id).addEventListener('change',refresh);
$('search').addEventListener('input',renderFacts);$('facttopic').addEventListener('change',renderFacts);refresh();
'''
auditpath=ROOT/'findings/data/idrbench-discipline/audit.html'
audit=auditpath.read_text() if auditpath.exists() else '<p class="note">原文抽查记录待补齐。</p>'
payload=json.dumps(D,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
out=HEAD+'<script>const D='+payload+';const P='+json.dumps(P)+';const AUDIT='+json.dumps(audit,ensure_ascii=False)+';'+JS+'</script></body></html>'
p=ROOT/'findings/2026-09-07-discipline-flow.html';p.write_text(out);print(p,len(out))
